<script lang="ts">import PageShell from '$lib/components/PageShell.svelte';import {listings} from '$lib/api';import type {Listing} from '$lib/types';let items=$state<Listing[]>([]),loading=$state(true),error=$state('');listings.all().then(r=>items=r.items).catch(e=>error=e.message).finally(()=>loading=false)</script><PageShell eyebrow="THE MARKETPLACE" title="Organic inputs, nearby."><div class="toolbar"><input placeholder="Search by waste, producer or place"/><button class="btn ghost">Filter</button></div>{#if loading}<p class="state">Loading listings…</p>{:else if error}<p class="alert">{error}</p>{:else if !items.length}<p class="state">No listings yet. Check back soon.</p>{:else}<div class="cards">{#each items as item}<a class="listing" href={`/marketplace/${item.id}`}><div class="thumb">♻</div><div class="listing-body"><p class="muted">{item.producerName} · {item.location}</p><h3>{item.title}</h3><div class="listing-foot"><strong>{item.priceSats.toLocaleString()} sats / {item.unit}</strong><span>{item.quantity} available</span></div></div></a>{/each}</div>{/if}</PageShell>
